alter table public.matching_intelligence_examples add constraint matching_intelligence_examples_evidence_strength_check CHECK ((evidence_strength = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'very_high'::text])));
alter table public.matching_intelligence_examples add constraint matching_intelligence_examples_label_check CHECK ((match_label = ANY (ARRAY['match'::text, 'non_match'::text, 'condition_problem'::text, 'valid_match_poor_opportunity'::text, 'availability_system'::text, 'needs_review'::text])));
alter table public.matching_intelligence_examples add constraint matching_intelligence_examples_label_type_check CHECK ((label_type = ANY (ARRAY['positive_identity'::text, 'negative_identity'::text, 'condition_issue'::text, 'business_issue'::text, 'availability_system'::text, 'unknown'::text])));
alter table public.matching_intelligence_examples add constraint matching_intelligence_examples_pkey PRIMARY KEY (matching_intelligence_example_id);
alter table public.sourcing_actions add constraint sourcing_actions_pkey PRIMARY KEY (action_id);
alter table public.sourcing_blocked_asins add constraint sourcing_blocked_asins_pkey PRIMARY KEY (asin);
alter table public.sourcing_ebay_candidates add constraint sourcing_ebay_candidates_ebay_item_id_key UNIQUE (ebay_item_id);
alter table public.sourcing_ebay_candidates add constraint sourcing_ebay_candidates_listing_status_check CHECK ((listing_status = ANY (ARRAY['active'::text, 'ended'::text, 'unknown'::text])));
alter table public.sourcing_ebay_candidates add constraint sourcing_ebay_candidates_pkey PRIMARY KEY (candidate_id);
alter table public.sourcing_listing_snapshots add constraint sourcing_listing_snapshots_event_check CHECK ((snapshot_event = ANY (ARRAY['opportunity_created'::text, 'dismissed'::text, 'watching'::text, 'purchased'::text, 'offer_made'::text, 'roi_snoozed'::text, 'availability_refresh'::text, 'backfill'::text])));
alter table public.sourcing_listing_snapshots add constraint sourcing_listing_snapshots_pkey PRIMARY KEY (listing_snapshot_id);
alter table public.sourcing_opportunities add constraint sourcing_opportunities_pkey PRIMARY KEY (opportunity_id);
alter table public.sourcing_sales_velocity_suppressions add constraint sourcing_sales_velocity_suppressions_pkey PRIMARY KEY (suppression_id);
alter table public.sourcing_sales_velocity_suppressions add constraint sourcing_sales_velocity_suppressions_status_check CHECK ((status = ANY (ARRAY['active'::text, 'released'::text])));
alter table public.sourcing_seed_asins add constraint sourcing_seed_asins_pkey PRIMARY KEY (seed_id);
alter table public.sourcing_seed_asins add constraint sourcing_seed_asins_source_mode_check CHECK ((source_mode = ANY (ARRAY['recent_sales'::text, 'full_listings'::text, '1_recently_sold'::text, '2_purchased_not_sent'::text, '3_catalog_remaining'::text])));
alter table public.sourcing_settings add constraint sourcing_settings_pkey PRIMARY KEY (setting_id);
create unique index active_velocity_unique on public.sourcing_sales_velocity_suppressions(asin) where status='active';
